INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist es wahr, dass ein sich selbst aufrufender Algorithmus immer langsamer als Iteration ist?', 2, '[{"text": "Nein", "correct": true, "because": "Effizienz hängt von Optimierung ab"}, {"text": "Ja", "correct": false, "because": "Nicht immer langsamer"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist entscheidend, damit ein selbstaufrufender Algorithmus endet?', 3, '[{"text": "Abbruchbedingung", "correct": true, "because": "Verhindert Endlosschleifen"}, {"text": "Hohe Speichergröße", "correct": false, "because": "Irrelevant für Ende"}, {"text": "Viele Parameter", "correct": false, "because": "Keine Rolle für Abbruch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme eignen sich für einen selbstaufrufenden Ansatz?', 5, '[{"text": "Baumdurchläufe", "correct": true, "because": "Natürliche Teilung möglich"}, {"text": "Fakultätsberechnung", "correct": true, "because": "Klarer rekursiver Aufbau"}, {"text": "Lineare Suche", "correct": false, "because": "Iteration effizienter"}, {"text": "Datenbankabfragen", "correct": false, "because": "SQL nicht rekursiv"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein rekursiver Aufruf braucht eine Abbruchbedingung. b) Er ist immer speicherschonend.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Stack wächst"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich einen selbstaufrufenden Algorithmus schreibe?', 4, '[{"text": "Stack-Überlauf", "correct": false, "because": "Kritisches Risiko"}, {"text": "Abbruchbedingung", "correct": false, "because": "Notwendig für Ende"}, {"text": "Code-Kommentare", "correct": true, "because": "Hilfreich, aber nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein selbstaufrufender Ansatz für lineare Aufgaben optimal ist?', 2, '[{"text": "Nein", "correct": true, "because": "Iteration oft effizienter"}, {"text": "Ja", "correct": false, "because": "Mehr Overhead"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technik hilft, Speicherprobleme bei tiefen Aufrufen zu vermeiden?', 4, '[{"text": "Tail-Rekursion", "correct": true, "because": "Optimiert Stack-Nutzung"}, {"text": "Mehr Parameter", "correct": false, "because": "Erhöht Komplexität"}, {"text": "Globale Variablen", "correct": false, "because": "Keine Optimierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass selbstaufrufende Algorithmen immer leicht zu debuggen sind. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Stack-Trace kann komplex sein"}, {"text": "Ja", "correct": false, "because": "Debugging oft schwierig"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein rekursiver Ansatz für Fakultät besser als Iteration?', 2, '[{"text": "Nein", "correct": true, "because": "Iteration ist effizienter"}, {"text": "Ja", "correct": false, "because": "Mehr Overhead bei Rekursion"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen einen rekursiven Algorithmus effektiv?', 5, '[{"text": "Klare Abbruchbedingung", "correct": true, "because": "Sichert Beendigung"}, {"text": "Einfache Teilprobleme", "correct": true, "because": "Fördert Struktur"}, {"text": "Hohe Schleifenzahl", "correct": false, "because": "Iteration, nicht Rekursion"}, {"text": "Viele globale Variablen", "correct": false, "because": "Kompliziert Logik"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich einen Baum rekursiv durchlaufe?', 4, '[{"text": "Teilung in Unterbäume", "correct": true, "because": "Nutzt Struktur effizient"}, {"text": "Lineare Verarbeitung", "correct": false, "because": "Nicht für Bäume geeignet"}, {"text": "Maximale Tiefe", "correct": false, "because": "Risiko für Overflow"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Merge-Sort nutzt Selbstaufrufe. b) Es ist immer schneller als Iteration.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Geschwindigkeit ähnlich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für einen funktionierenden rekursiven Algorithmus?', 3, '[{"text": "Abbruchbedingung", "correct": false, "because": "Verhindert Endlosschleife"}, {"text": "Teilprobleme", "correct": false, "because": "Kern der Rekursion"}, {"text": "GUI-Oberfläche", "correct": true, "because": "Kein funktionaler Nutzen"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, wie ich einen rekursiven Algorithmus debugge?', 4, '[{"text": "Stack-Trace analysieren", "correct": true, "because": "Zeigt Aufrufkette"}, {"text": "Nur Ausgabe prüfen", "correct": false, "because": "Zu oberflächlich"}, {"text": "Code löschen", "correct": false, "because": "Keine Lösung"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Selbstaufrufe immer ineffizient sind. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Mit Optimierung effizient"}, {"text": "Ja", "correct": false, "because": "Kontextabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Problem ist für rekursive Lösungen ideal?', 4, '[{"text": "Türme von Hanoi", "correct": true, "because": "Natürliche Teilung"}, {"text": "Lineare Addition", "correct": false, "because": "Iteration besser"}, {"text": "Datenbankabfrage", "correct": false, "because": "SQL nicht rekursiv"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Verbraucht jeder rekursive Aufruf Speicher?', 2, '[{"text": "Ja", "correct": true, "because": "Jeder Aufruf nutzt Stack"}, {"text": "Nein", "correct": false, "because": "Stack wächst"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein rekursiver Ansatz?', 5, '[{"text": "Klarer Code", "correct": true, "because": "Spiegelt Struktur wider"}, {"text": "Einfache Logik", "correct": true, "because": "Teilt Probleme auf"}, {"text": "Wenig Speicher", "correct": false, "because": "Stack kann wachsen"}, {"text": "Schnelle Ausführung", "correct": false, "because": "Nicht immer schneller"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem rekursiven Algorithmus unwichtig?', 3, '[{"text": "Abbruchbedingung", "correct": false, "because": "Sichert Beendigung"}, {"text": "Teilprobleme", "correct": false, "because": "Kern der Logik"}, {"text": "Farbschema", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie gehe ich vor, wenn ich eine Fibonacci-Folge rekursiv berechne?', 4, '[{"text": "Zwei Teilaufrufe mit Abbruch", "correct": true, "because": "Summiert Vorgänger"}, {"text": "Lineare Schleife", "correct": false, "because": "Nicht rekursiv"}, {"text": "Nur letzte Zahl speichern", "correct": false, "because": "Fehlt Rekursion"}]');
